  'impostazioni.aspetto.navigazioneHint': 'Choisissez le style du menu. La barre flottante est un dock translucide en bas (style iOS) ; la barre latérale est le menu classique repliable à gauche ; la barre supérieure place la navigation en haut, sur une seule ligne. Flottante et supérieure envoient les éléments en trop dans le menu « Plus ».',
