  'impostazioni.sdi.title': 'API intermédiaire SDI',
  'impostazioni.sdi.intro': 'Configurez l\'API de l\'intermédiaire pour l\'envoi des factures électroniques au Système d\'Échange (SDI). Le logiciel générera le fichier XML FatturaPA et l\'enverra à l\'URL configurée.',
  'impostazioni.sdi.comeFunziona': 'Comment fonctionne l\'envoi',
  'impostazioni.sdi.guidaP1': 'Devenir un canal accrédité directement auprès du Système d\'Échange nécessite des exigences techniques et sociétaires qu\'un projet personnel/open source n\'a pas. La voie réaliste consiste à s\'appuyer sur un intermédiaire déjà accrédité offrant l\'envoi et la réception via API (Aruba, Fatture in Cloud, ou un autre fournisseur de votre choix).',
  'impostazioni.sdi.guidaStep1': 'Vérifiez sur votre compte de l\'intermédiaire que le forfait inclut l\'accès API (pas seulement le portail web) et récupérez l\'endpoint et la clé dans la section développeurs/API de leur site.',
  'impostazioni.sdi.guidaStep2': 'Choisissez le fournisseur ci-dessous : pour Aruba et Fatture in Cloud, l\'URL se remplit automatiquement ; avec « Autre intermédiaire », saisissez l\'endpoint fourni par votre fournisseur.',
  'impostazioni.sdi.guidaStep3': 'Collez la clé API et enregistrez : dès lors, « Envoyer au SDI » sur les factures utilisera cette configuration.',
  'impostazioni.sdi.guidaFallback': 'Sans rien configurer ici, chaque facture reste téléchargeable en XML FatturaPA valide (menu ⋮ sur la facture → « Télécharger le XML FatturaPA ») : vous pouvez le charger vous-même sur le portail de votre intermédiaire, ou gratuitement sur « Fatture e Corrispettivi » de l\'Agence des recettes italienne.',
  'impostazioni.sdi.provider': 'Fournisseur',
  'impostazioni.sdi.altroIntermediario': 'Autre intermédiaire (URL + clé)',
  'impostazioni.sdi.ficNote': 'L\'intégration automatique complète avec Fatture in Cloud (connexion et envoi/réception en un clic) arrivera bientôt. Pour l\'instant, vous pouvez utiliser l\'envoi générique en saisissant l\'endpoint API et la clé de votre compte.',
  'impostazioni.sdi.urlApi': 'URL API SDI',
  'impostazioni.sdi.apiKey': 'Clé API',
  'impostazioni.backup.title': 'Sauvegarde automatique quotidienne',
