  'impostazioni.dati.doveHint': 'Tout le logiciel de gestion vit dans un dossier sur votre ordinateur. Vous pouvez l\'ouvrir, le déplacer où vous voulez (même dans Dropbox, OneDrive ou iCloud) et l\'utiliser depuis un autre ordinateur.',
  'impostazioni.dati.cartella': 'Dossier :',
  'impostazioni.dati.colFile': 'Fichier',
  'impostazioni.dati.spostaCartella': 'Déplacer le dossier de données…',
