  'impostazioni.dati.avviaAllAccensioneHint': 'Au démarrage du système, Ordeva se lance seul et reste dans la zone de notification (barre système). Fermer la fenêtre l\'y laisse : pour vraiment quitter, utilisez « Fermer en sécurité » ou le menu de la barre système.',
  'impostazioni.dati.cronologiaTitle': 'Historique des versions (instantanés)',
  'impostazioni.dati.cronologiaHint': 'Ordeva enregistre seul des « points de restauration » de vos données (toutes les quelques heures). Vous pouvez en créer un à la volée ou revenir à un point précédent. Avant toute restauration, une copie de sécurité de l\'état actuel est de toute façon enregistrée.',
