  'impostazioni.dati.colDataOra': 'Date et heure',
  'impostazioni.dati.nessunoSnapshot': 'Aucun instantané pour le moment. Un sera créé automatiquement sous peu.',
  'impostazioni.dati.cifraturaTitle': 'Chiffrement et mot de passe',
  'impostazioni.dati.cifraturaHint': 'La protection par mot de passe est désormais par archive : chaque archive est chiffrée avec son propre mot de passe (demandé à son ouverture) et ses sauvegardes ne sont lisibles qu\'avec celui-ci. Définissez ou supprimez le mot de passe depuis l\'écran Archives (élément du menu de gauche).',
  'impostazioni.dati.multiComputerTitle': 'Utilisation sur plusieurs ordinateurs (Dropbox)',
  'impostazioni.dati.multiComputerHint': 'Si vous conservez le dossier de données dans Dropbox, vous pouvez aussi utiliser Ordeva depuis un autre ordinateur, un à la fois. Une fois terminé, utilisez « Fermer en sécurité » : Ordeva consolide les données dans un seul fichier afin que Dropbox les synchronise avant que vous n\'ouvriez l\'application ailleurs. L\'ouvrir simultanément sur deux ordinateurs peut corrompre les données.',
