  'glossario.reverseCharge.titolo': 'Reverse charge (autoliquidation)',
  'glossario.reverseCharge.descrizione': 'Dans certains secteurs, la TVA est acquittée par le client au lieu du fournisseur. La facture doit être émise sans TVA.',
  'glossario.esterometro.titolo': 'Esterometro (déclaration transfrontalière)',
